insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('1', 'Weak Sales Disguised as a Market Problem', 'external_to_internal', 'Our sales are weak — the market is not ready or the timing is off', 'The problem is external — wrong market, wrong timing, wrong channel', 'Sales aversion and fear of rejection rooted in a product-centric mindset. The founder avoids the discomfort of direct selling by staying in product mode. Confirmation bias reinforces the belief that the market is at fault when the founder has not actually engaged in disciplined sales activity.', '["Walk me through what your sales process looks like right now — what happens between a lead appearing and a deal closing or dying?", "Of the leads you get today, what percentage converts — and what happens to the ones that do not?", "How do you personally feel in the moments before a sales call or a follow-up message?", "When did you last speak to a customer who did not buy — and do you know why they did not?", "How much of your week this month was spent in actual selling conversations versus building the product or working on the business internally?"]', '["GTM-001", "GTM-006", "SAL-001", "SAL-002"]', '["RC-019", "RC-028", "RC-097", "RC-100"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('2', 'No Product-Market Fit Disguised as a Timing Problem', 'external_to_internal', 'We have not found PMF yet — the market is not ready for this', 'The world needs to catch up to what we are building — it is a timing issue', 'Confirmation bias and fear of pivoting. The founder mistakes optimism for evidence and treats customer surveys as echo chambers — valuing early traction graphs over real fit signals. What feels like conviction is actually avoidance of the painful reality that the product does not solve a problem people prioritise paying for.', '["When you say the market is not ready — what specific evidence has told you that? Can you describe what a customer did or said?", "Have you spoken to customers who stopped using the product or did not buy — and what did they tell you?", "If you had to describe the problem your product solves in one sentence to someone who has never heard of you — what would you say?", "What would need to be true for you to consider that the product itself might need significant change rather than the market needing time?", "What is the one piece of customer feedback you have received that was the hardest to hear — and what did you do with it?"]', '["IVA-001", "IVA-005", "PRD-005"]', '["RC-001", "RC-005", "RC-108", "RC-109"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('3', 'Team Performance Problem Disguised as a Hiring Problem', 'external_to_internal', 'My team is not performing — I keep hiring the wrong people', 'The problem is the quality of the people I can attract and hire', 'Founder insecurity, micromanagement, and hero syndrome setting cultural norms of distrust. Employees mirror the founder''s behaviour and normalise dysfunction. The team appears to be the problem when the founder''s leadership behaviour is the actual root cause — toxic or micromanaging founders create exactly the underperformance they then complain about.', '["How do you assign work to your team — do you write a brief or explain verbally what needs to happen?", "When someone on the team makes a mistake, walk me through what typically happens next", "How often do you check on work in progress — and what does that check-in look like?", "What does your team say when you ask them what gets in the way of doing their best work?", "If I asked your team right now what the top three priorities are this week, would they all give me the same answer?"]', '["TM-002", "TM-004", "TM-006"]', '["RC-099", "RC-102", "RC-103", "RC-115"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('4', 'Cash Flow Crisis Disguised as a Revenue Problem', 'external_to_internal', 'We are running out of cash — we just need more revenue', 'This is a sales and revenue problem — more customers will fix the cash situation', 'Over-optimism bias and reluctance to face unpleasant financial data. The founder''s internal emotional state directly creates the external cash crisis. Founders produce optimistic forecasts, ignore warning signs, and mistake passion for financial discipline. The cash crisis is almost never a surprise — it was visible in the numbers months earlier to anyone willing to look.', '["How many months of runway do you have right now — and how did you calculate that?", "When did you last review your actual burn rate versus your projected burn rate — and what was the gap?", "Walk me through what you expected revenue to look like this month three months ago versus what it actually is", "Is there any financial data you have been avoiding looking at recently — even briefly?", "What would you tell a friend who was in exactly your financial position right now but could see it from outside?"]', '["OPS-004", "FND-001", "FND-007"]', '["RC-106", "RC-112", "RC-118", "RC-119"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('5', 'No Business Growth Disguised as a Market Problem', 'external_to_internal', 'Growth has stalled — the market is saturated or competition is too strong', 'External forces are blocking growth — competition, market maturity, or economic conditions', 'Fixed mindset and fear of failure in the founder. A founder''s internal resistance to bold moves directly creates flat growth. Employees adopt the founder''s fear-driven conservatism — they see no clear path forward and mirror the caution they observe at the top. The business stops moving because the founder has stopped moving first.', '["What is the one bold move you have been considering but have not made yet — and what is stopping you?", "When did you last do something in the business that felt genuinely risky — and what happened?", "If you were starting fresh today with what you know, what would you do differently right now?", "How does your team describe the company''s direction when you ask them — is there excitement or resignation?", "What would need to be true for you to believe that growth is actually possible from where you are right now?"]', '["IVA-005", "GTM-007", "SCL-035"]', '["RC-109", "RC-118", "RC-123", "RC-124"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('6', 'Poor GTM Disguised as a Product Problem', 'external_to_internal', 'Our go-to-market is not working — the product needs more features before we can sell it', 'The product is not ready enough yet — once it is complete customers will come', 'Avoidance of market reality and a product-over-customer mindset. The belief that a good product sells itself is one of the most damaging internal misbeliefs a founder can hold. Founders avoid uncomfortable customer conversations and hard selling by returning to product work. The GTM fails not because the product is incomplete but because the founder has not built the discipline of selling.', '["How many customer conversations did you have this week that were specifically about selling — not building or feedback?", "When you think about improving the product versus going out and selling what exists — which one feels more natural and comfortable?", "What would the product need to look like before you felt comfortable selling it aggressively? And is that bar realistic?", "Have you ever sold something — a product, a service, an idea — outside this startup? What was that like?", "If you had to generate ten qualified conversations this week with no product changes allowed, what would you do?"]', '["GTM-001", "GTM-002", "GTM-004", "GTM-006"]', '["RC-008", "RC-009", "RC-013", "RC-028"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('7', 'Fundraising Failure Disguised as an Investor Problem', 'external_to_internal', 'We cannot raise funding — investors do not understand our vision', 'The problem is investor sophistication or market sentiment — the right investor just has not appeared yet', 'Overconfidence and denial. Founders who internally cannot accept the weaknesses of their business lose investor credibility immediately — investors are trained to detect when a founder cannot see their own blind spots. The founder''s need to appear strong and certain directly causes the fundraising failure. After funding, 75% of startups still fail — investment is not the solution when internal clarity is missing.', '["Describe your pitch in one sentence — the problem, the solution, and why you specifically", "What is the most common objection or question you get from investors — and what do you say in response?", "How do you feel in the moments before an investor meeting — and how do you feel if the feedback is critical?", "Have you ever asked an investor who passed why they passed — and if yes, what did they say?", "If an investor told you your business model had a fundamental flaw, what would your first reaction be — internal or external?"]', '["FND-003", "FND-005", "FND-006"]', '["RC-030", "RC-106", "RC-112", "RC-113"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('8', 'Operational Chaos Disguised as a Growth Problem', 'external_to_internal', 'We cannot handle the growth — we are breaking under the demand', 'The business is growing faster than we can manage — this is a good problem to have', 'Fear of losing control and neglect of process-building. Founders who cannot let go create organisations where new demand feels like a burden rather than an opportunity. The startup''s own machine becomes the bottleneck. The operational chaos is not caused by too much growth — it was always there, just manageable when the founder could personally plug the gaps. Growth made the absence of systems visible.', '["Walk me through what happens when a new customer or order arrives — who does what, and is that written down anywhere?", "What decisions in the business can your team make without you — and what requires your involvement?", "When something goes wrong operationally, what is the process for fixing it and making sure it does not happen again?", "How much of your week is spent doing work that someone else in the team could theoretically do if you explained it to them?", "If you were unavailable for two weeks — no messages, no calls — what would actually break, and what would the team handle fine?"]', '["OPS-001", "OPS-002", "OPS-003"]', '["RC-040", "RC-041", "RC-042", "RC-099"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('9', 'High Team Turnover Disguised as a Hiring or Compensation Problem', 'external_to_internal', 'We keep losing good people — we cannot compete on salary with larger companies', 'Compensation and company size are the reason people leave — it is a structural disadvantage', 'Founder insecurity, blame behaviour, and absence of psychological safety. Employees leave cultures, not companies — and in an early startup, the culture is the founder. What looks like a hiring or retention problem on the outside is almost always a leadership behaviour problem on the inside. People do not leave for 20% more salary when they feel genuinely trusted, valued, and part of something meaningful.', '["When a team member leaves, do you do an honest exit conversation — and if yes, what do they actually say?", "What happens in your team when someone makes a mistake — walk me through the last time that happened", "If I asked your longest-serving team member what they find most difficult about working with you, what would they say?", "When was the last time someone on the team disagreed with you publicly — and what happened next?", "Do people on your team feel comfortable telling you bad news — and what is your evidence for that?"]', '["TM-006", "SCL-028", "SCL-029"]', '["RC-113", "RC-115", "RC-116", "RC-121"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('10', 'Product Direction Constantly Changing Disguised as Market Responsiveness', 'external_to_internal', 'We keep pivoting because the market keeps sending us new signals', 'We are being responsive and agile — adapting to what customers and the market are telling us', 'Indecision rooted in fear of commitment and insecurity about choices. Repeatedly changing product strategy is usually fear-driven — founders who are unwilling to commit change direction not because the market demands it but because they are afraid of being wrong about any single direction. Endless product churn is not a product problem. It is a founder confidence and clarity problem showing up in the roadmap.', '["Walk me through the last three significant product direction changes — what triggered each one?", "How long do you typically give a direction before you decide it is not working — and what does not working look like?", "What is the one product direction you were most excited about that you walked away from — and do you still think it was the right call?", "When you change direction, how does the team respond — and how does that response affect your next decision?", "If you had to commit to one product direction for the next six months with no changes allowed, what would it be — and what makes that hard to say?"]', '["PRD-005", "IVA-005", "SCL-038"]', '["RC-037", "RC-107", "RC-110", "RC-116"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('11', 'Burnout Disguised as a Business Structure Problem', 'internal_to_external', 'I feel burned out — I need to hire more people or restructure the business', 'The problem is structural — too much work for one person, wrong team configuration', 'The burnout is real, but the root cause is not structural — it is the founder''s inability to delegate, the absence of any coping or recovery system, and identity fusion with the business. Hiring more people into a broken delegation culture will not solve burnout. The founder will just find new things to take back. The internal pattern must change before any structural change will hold.', '["When you imagine hiring someone to take tasks off your plate — which tasks actually feel safe to hand over completely?", "Have you delegated work before and then taken it back — and if yes, what triggered that?", "When did you last take a full day off — not a half day, not an evening, a full day where you did not check in once?", "What does your week look like when you are not burned out versus now — what is different?", "If hiring solved the problem and you suddenly had free time, what would you actually do with it?"]', '["OPS-002", "SCL-004", "SCL-011"]', '["RC-099", "RC-100", "RC-101", "RC-102"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('12', 'Fear of Failure Disguised as Strategic Patience', 'internal_to_external', 'We are being strategic — waiting for the right moment to make our move', 'This is disciplined strategy — timing matters and we are not ready yet', 'Fear of failure is creating avoidance behaviour that is being rationalised as strategic patience. The right moment never arrives because the fear is not resolved by time — it is resolved only by action. The longer the founder waits, the stronger the avoidance loop becomes, and the more elaborate the strategic justifications for inaction.', '["What specifically needs to be true before the right moment arrives — can you name it precisely?", "How long have you been waiting for this right moment — and has the definition of what makes it right changed over that time?", "What is the worst realistic outcome if you moved now rather than waiting — and how would you recover from it?", "If a competitor made the move you are waiting to make and it worked, how would that feel?", "Is there a version of fear in this — not just strategy — that is honest to name right now?"]', '["IVA-005", "GTM-001", "FND-006"]', '["RC-005", "RC-109", "RC-123", "RC-124"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('13', 'Imposter Syndrome Disguised as a Skills Gap', 'internal_to_external', 'I need more training, credentials, or experience before I am ready to do this properly', 'The gap is a knowledge or skills gap — I need to learn more before I can act with confidence', 'Imposter syndrome masquerading as a skills deficiency. The founder has enough capability to take the next step — the blocker is not missing knowledge but the internal belief that they are not the kind of person who belongs in this role. Acquiring more credentials rarely resolves imposter syndrome because the bar for readiness keeps moving — it is not a training problem, it is a self-worth problem.', '["If someone else with exactly your current skills and experience were doing what you are trying to do, would you think they were qualified — or would you also think they needed more preparation?", "What is the specific credential or experience you feel you are missing — and do you actually know anyone in this role who has it?", "When you have been confident in the past — in any area of your life — what was different about how you felt about yourself?", "Have you ever done something well that you felt unqualified for beforehand — and what happened?", "What would you tell someone else who had exactly your background and was hesitating for exactly the reasons you are hesitating?"]', '["IVA-007", "FND-005", "TM-003"]', '["RC-122", "RC-123", "RC-118", "RC-106"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('14', 'Identity Fusion Disguised as Founder Dedication', 'internal_to_external', 'I am completely dedicated to this — I give everything to the business', 'This level of dedication is what success requires — total commitment is a virtue', 'Identity fusion with the business is being celebrated as dedication when it is actually a psychological risk factor. When the company is everything, any business setback becomes a personal crisis. Decision-making quality degrades because every choice feels existential. The founder cannot take the strategic distance needed to make good calls because they are too close to the outcome emotionally.', '["If the company had a difficult month — revenue down, team problems, investor pressure — how does that affect how you feel about yourself as a person?", "Who are you outside of being the founder of this company — can you describe yourself without referencing it?", "What activities or relationships existed in your life before the company that you have let go of — and why?", "If a close friend asked you how you were doing right now — not the company, you — what would you honestly say?", "What would it mean about you personally if the company failed — not practically, but about who you are?"]', '["SCL-043", "SCL-044", "OPS-002"]', '["RC-096", "RC-101", "RC-107", "RC-115"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('15', 'Decision Paralysis Disguised as Thoroughness', 'internal_to_external', 'I want to make sure we have all the information before we commit to this direction', 'I am being responsible and rigorous — good decisions require complete information', 'Decision paralysis driven by fear of being wrong. The information needed to make the decision with certainty does not exist and never will — this is the nature of startup decisions. The thoroughness is real but it is serving as a justification for avoidance. Every week of delay has a cost: competitors move, the team loses confidence, and the window of opportunity narrows.', '["What is the specific piece of information you are waiting for — and is there a realistic way to get it in the next two weeks?", "How long has this decision been pending — and what additional information have you gathered in that time?", "What is the cost of not deciding for another month — to the business, to the team, to the opportunity?", "If you had to make this decision right now with only what you know, which way would you go — and what does your gut say?", "What is the honest fear underneath the request for more information — what are you most afraid of getting wrong?"]', '["SCL-010", "SCL-048", "OPS-005"]', '["RC-110", "RC-112", "RC-116", "RC-120"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('16', 'Hero Syndrome Disguised as Quality Standards', 'internal_to_external', 'I stay involved because I have the highest standards and things go wrong when I step back', 'My involvement is necessary for quality — the team is not yet ready to work independently', 'Hero syndrome and perfectionism creating a bottleneck that is rationalised as quality management. The team is not underperforming because they lack capability — they are underperforming because the founder never gave them genuine authority or room to grow. The standard being enforced is not a quality standard — it is a control standard. And the team has learned not to try because they know the founder will redo it anyway.', '["Can you describe the last task you delegated that was done well enough — even if not exactly how you would have done it?", "When someone on the team does something differently from how you would do it but it still works, what is your reaction?", "If the standard you are holding the team to was written down and shared with them — would they recognise it as the standard they were given?", "What would need to be true about your team for you to trust them to make a decision in their own area without involving you?", "If you were not able to be involved for a month — genuinely not available — what would happen, and is that answer different from what you fear would happen?"]', '["OPS-002", "SCL-004", "SCL-011", "SCL-044"]', '["RC-099", "RC-102", "RC-103", "RC-104"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('17', 'Confirmation Bias Disguised as Market Confidence', 'internal_to_external', 'We have validated this thoroughly — the market feedback has been very positive', 'We have done the work — the evidence supports our direction', 'Confirmation bias causing the founder to selectively collect and weight evidence that confirms what they already believe. Feedback from people who like the idea is amplified. Negative signals are explained away or attributed to outliers. The founder genuinely believes they have validated — but the validation process was designed to confirm, not to challenge.', '["Who gave you the most positive feedback about this — and what is their relationship to you?", "Can you describe the most critical piece of feedback you received during validation — and what did you do with it?", "Have you specifically sought out people who would be skeptical of this idea and asked for their honest opinion?", "Of the people who said positive things, how many have actually paid or committed to paying?", "What would a completely unbiased person with no stake in your success say about the evidence you have collected?"]', '["IVA-001", "IVA-006", "GTM-002"]', '["RC-001", "RC-003", "RC-108", "RC-114"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('18', 'Isolation Disguised as Focus', 'internal_to_external', 'I have cut out distractions and I am fully focused on building right now', 'Isolation from networks and communities is a deliberate choice that is serving the business', 'Psychological isolation and the absence of a support network being rationalised as focused execution. The founder is alone not because isolation serves the business but because reaching out feels vulnerable, and vulnerability feels dangerous. The result is compound decision-making without a sounding board, accumulated stress without an outlet, and blind spots that never get challenged.', '["When you are stuck on a hard decision, who do you call — and is there genuinely someone in that role?", "When was the last time someone who knows you well and understands building challenged a decision you had already made — and what happened?", "How are you actually doing — not the business, you — and when did you last say that honestly out loud to someone?", "What communities of founders or builders have you been part of — and when did you last engage with them?", "If you described the last month of your life to someone who cared about you — not as a founder, as a person — what would they say?"]', '["TM-003", "TM-005", "SCL-033"]', '["RC-097", "RC-120", "RC-124", "RC-121"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('19', 'Sunk Cost Trap Disguised as Commitment and Resilience', 'internal_to_external', 'We have invested too much to stop now — true founders do not quit when things get hard', 'Continuing is strength — quitting would mean the sacrifice was wasted', 'The sunk cost fallacy and loss aversion being framed as commitment and resilience — two genuinely admirable qualities. The confusion between persisting through a genuine temporary difficulty versus continuing to invest in a direction that the evidence says is wrong is one of the most costly blind spots in entrepreneurship. Resilience is not the same as refusing to pivot. Commitment to a goal is not the same as commitment to a method.', '["If you were starting fresh today with the same resources but none of what you have already built, would you choose exactly this path — and if not, what would you change?", "What would the data need to show for you to consider that continuing in this direction is not the right call?", "Is there a difference between believing in the goal and believing in this specific method of reaching it — and if yes, how certain are you that this method is right?", "Who has told you it might be time to change direction — and what was your honest internal reaction when they said it?", "What is the story you will tell yourself if this does not work — and is there a version of that story where the brave decision was to change course earlier?"]', '["IVA-005", "SCL-035", "SCL-038"]', '["RC-107", "RC-109", "RC-113", "RC-115"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
insert into "blind_spots" ("blind_spot_id", "blind_spot_name", "blind_spot_type", "what_founder_says", "what_founder_thinks", "what_it_actually_is", "probe_questions", "linked_problem_ids", "linked_root_cause_ids", "created_at", "updated_at") values ('20', 'Overconfidence Disguised as Vision and Conviction', 'internal_to_external', 'I know this market better than anyone — the vision is clear and I am confident in the direction', 'My conviction is evidence of insight — I have a right to be confident because I have thought about this deeply', 'Overconfidence bias creating a systematic blind spot to contradictory evidence. 81% of founders believe they have a 70%+ chance of success despite real failure rates. The founder''s certainty is not a function of the quality of their evidence — it is a function of how long they have been inside their own thinking. True confidence and overconfidence feel identical from inside. The difference is only visible from outside.', '["What is the strongest argument against your current direction — not from a competitor, but from the evidence you have seen yourself?", "When did you last genuinely change your mind about something important in the business based on external evidence — and what was that evidence?", "What do your most critical advisors or investors think about the direction — not the ones who are supportive, the skeptical ones?", "If everything you currently believe about the market turned out to be wrong, what would the first visible sign of that be?", "What are you most certain about in this business — and what would it take for you to become uncertain about that specific thing?"]', '["IVA-001", "IVA-005", "FND-005", "GTM-004"]', '["RC-106", "RC-108", "RC-112", "RC-114"]', '2026-07-10 17:15:57.409904+00', '2026-07-10 17:15:57.409904+00') on conflict do nothing;
